"""汉字 → 拼音首字母（离线、零依赖、自包含映射表）。

ERP 的智能指令要支持「给我 zgp 的对账单」这类拼音首字母找人：
zgp = 周广平（联系人）。表由 pypinyin 一次性生成，覆盖 CJK 基本区
0x4E00 ~ 0x9FA5（20902 个码位，其中 20892 个有读音）。
多音字取最常用读音（重→z、长→c、行→x）；'?' = 该码位无读音，匹配时跳过。

只提供一个函数：`pinyin_initials(text)`。
"""
from __future__ import annotations

import re
from functools import lru_cache

_TABLE = "?dqdfmsd?????xqbpfdwo??whlypcbjcc?dmbzpbzz?"
_TABLE_START = 0x4e00
_TABLE_END = 0x9fa5


@lru_cache(maxsize=4096)
def pinyin_initials(text: str | None) -> str:
    """汉字 → 拼音首字母串；ASCII 字母/数字原样保留（小写），其它字符跳过。"""
    value = str(text) if text is not None else ""
    out: list[str] = []
    for ch in value:
        code = ord(ch)
        if _TABLE_START <= code <= _TABLE_END:
            letter = _TABLE[code - _TABLE_START]
            if letter != "?":
                out.append(letter)
        elif ch.isascii() and ch.isalnum():
            out.append(ch.lower())
    return "".join(out)


import re


def is_latin_query(query: str | None) -> bool:
    """关键词是否纯拉丁字母/数字（只有这类输入才值得走拼音匹配）。"""
    return bool(re.fullmatch(r"[a-z0-9]+", str(query or "").strip().lower()))
